const raw = $json.output;

if (!raw) {
  throw new Error("AI Agent returned empty output");
}

let data;

try {
  data = typeof raw === "string" ? JSON.parse(raw) : raw;
} catch (error) {
  throw new Error("Invalid AI JSON: " + error.message);
}

const required = [
  "Intent",
  "Amount",
  "Date",
  "category",
  "Transaction Type",
  "Payment Method",
  "Reply"
];

for (const key of required) {
  if (!Object.prototype.hasOwnProperty.call(data, key)) {
    throw new Error(`Missing required field: ${key}`);
  }
}

const validIntents = [
  "Transaction",
  "Analysis",
  "General",
  "Clarification",
];

if (!validIntents.includes(data.Intent)) {
  throw new Error("Invalid Intent");
}

const validTypes = ["Expenses", "Income", "Unknown"];

if (!validTypes.includes(data["Transaction Type"])) {
  throw new Error("Invalid Transaction Type");
}

const validCategories = [
  "Income",
  "Essential",
  "Luxury",
  "Savings",
  "Investment",
  "Unknown"
];

if (!validCategories.includes(data.category)) {
  throw new Error("Invalid category");
}

const validMethods = [
  "Cash",
  "Wallet",
  "Instapay",
  "Visa",
  "Unknown"
];

if (!validMethods.includes(data["Payment Method"])) {
  throw new Error("Invalid Payment Method");
}

if (typeof data.Reply !== "string") {
  throw new Error("Reply must be a string");
}

if (data.Intent === "Transaction") {
  if (
    typeof data.Amount !== "number" ||
    !Number.isFinite(data.Amount) ||
    data.Amount <= 0
  ) {
    throw new Error("Transaction Amount must be a positive number");
  }

  if (
    data["Transaction Type"] !== "Expenses" &&
    data["Transaction Type"] !== "Income"
  ) {
    throw new Error("Invalid transaction direction");
  }

  if (!/^\d{4}-\d{2}-\d{2}$/.test(data.Date)) {
    throw new Error("Invalid transaction date format");
  }

  const date = new Date(data.Date + "T00:00:00Z");

  if (
    Number.isNaN(date.getTime()) ||
    date.toISOString().slice(0, 10) !== data.Date
  ) {
    throw new Error("Invalid transaction date");
  }
}


return [{ json: data }];
